#include <Arduino.h>
#include <Adafruit_GFX.h>    
#include <Adafruit_ST7735.h> 
#include <SPI.h>

// 配線は安全なD4, D5, D6のまま
#define TFT_RST    4   // 基板のD4
#define TFT_DC     5   // 基板のD5
#define TFT_CS     6   // 基板のD6

// ここは基本の3つ指定に戻します
Adafruit_ST7735 tft = Adafruit_ST7735(TFT_CS, TFT_DC, TFT_RST);

void setup() {
  // Chromebookの通知連打を防ぐ命綱
  Serial.begin(115200);
  delay(2000); 

  Serial.println("Starting LCD with forced slow speed..."); 

  // 液晶の初期化
  tft.initR(INITR_BLACKTAB); 

  // ★【ここが超重要！】★
  // 初期化した直後に、通信速度を「4MHz（超安全な遅さ）」に上書きして強制ロックします。
  // これでXIAOの爆速スピードに強烈なブレーキがかかります。
  SPI.beginTransaction(SPISettings(4000000, MSBFIRST, SPI_MODE0));

  // 画面を「青色」で塗りつぶす
  tft.fillScreen(ST7735_BLUE);

  // 文字の設定
  tft.setCursor(10, 50);          
  tft.setTextColor(ST7735_WHITE); 
  tft.setTextSize(2);             

  // 画面に文字を表示
  tft.println("Hello!");
}

void loop() {
  Serial.println("LCD is working safely at 4MHz.");
  delay(2000);
}
